insert into public.negotiations (id, customer_id, category_id, title, request_id, offer_id, business_id, counterparty_name, mode, state, baseline_cents, target_cents, current_offer_cents, recurrence, simulated, version, created_at, updated_at, messages) values ('00000000-0000-4000-8000-000000000501', '00000000-0000-4000-8000-000000000001', 'trades', 'Fence replacement with Ben''s Fencing & Gates', '00000000-0000-4000-8000-000000000301', '00000000-0000-4000-8000-000000000403', '00000000-0000-4000-8000-000000000101', 'Ben''s Fencing & Gates (demo)', 'approval', 'awaiting_counterparty', 550000, 460000, 510000, 'one_off', false, 0, '2026-11-12T04:18:13.109Z', '2026-11-13T04:18:13.109Z', '[{"id":"00000000-0000-4000-8000-000000005011","at":"2026-11-12T04:18:13.109Z","from":"ai","kind":"analysis","body":"Ben''s offer is $400 under your original $5,500 quote and has the longest warranty (7 years). Competing offers go as low as $4,400, but that one has no insurance and non-Colorbond panels. Suggested target: $4,600."},{"id":"00000000-0000-4000-8000-000000005012","at":"2026-11-13T04:18:13.109Z","from":"ai","kind":"sent","body":"Hi Ben, thanks for the quote. I have other licensed and insured offers in the high $4,000s. If you can do $4,600 with the same scope and 7-year warranty, I''m ready to book. — Alex","amountCents":460000,"approvedAt":"2026-11-13T04:18:13.109Z"}]'::jsonb);
insert into public.negotiations (id, customer_id, category_id, title, business_id, counterparty_name, mode, state, baseline_cents, target_cents, current_offer_cents, recurrence, simulated, version, created_at, updated_at, messages) values ('00000000-0000-4000-8000-000000000502', '00000000-0000-4000-8000-000000000001', 'telco', 'Home internet — StreamLine Broadband', '00000000-0000-4000-8000-000000000105', 'StreamLine Broadband (simulated)', 'approval', 'awaiting_approval', 12000, 8400, 12000, 'monthly', true, 0, '2026-11-13T04:18:13.109Z', '2026-11-13T04:18:13.109Z', '[{"id":"00000000-0000-4000-8000-000000005021","at":"2026-11-13T04:18:13.109Z","from":"ai","kind":"analysis","body":"Your bill is $120/month ($110 plan + $10 modem rental). After 4 years with no lock-in you''re a good candidate for a retention offer. Simulated market range for similar plans is $84–$102. Suggested target: $84/month."},{"id":"00000000-0000-4000-8000-000000005022","at":"2026-11-13T04:18:13.109Z","from":"ai","kind":"draft","pendingApproval":true,"amountCents":8400,"simulated":true,"body":"Hi StreamLine Broadband, I''ve been a customer for 4 years and I''m paying $120/month including modem rental. Comparable NBN 100 plans are available for less. I''d like to stay with you at $84/month. Can you offer that? — Alex"}]'::jsonb);
